// =============================================================================
// Module  : pdm_bram_player
// Project : P6 PDM-to-PCM Audio Front End
// Purpose : Streams 1-bit PDM from BRAM at 3.072 MHz
//           Used for standalone hardware demos when no physical PDM mic is attached.
//           Data is pre-generated by the Python sigma-delta golden model.
// =============================================================================

`timescale 1ns / 1ps

module pdm_bram_player #(
    parameter integer TOTAL_BITS = 192000, // 0.0625 seconds of PDM audio
    parameter integer ADDR_W     = 18,
    parameter         HEX_FILE   = "../../sim/vectors/pdm_test.hex"
)(
    input  wire        clk_pdm,    // 3.072 MHz clock
    input  wire        rst_n,
    input  wire        play_en,    // Enable streaming
    output reg         pdm_out,    // 1-bit serialized PDM data
    output reg  [ADDR_W-1:0] bit_idx
);

// Byte-packed ROM (each byte holds 8 PDM bits, MSB first)
localparam integer NUM_BYTES  = (TOTAL_BITS + 7) / 8;
localparam integer BYTE_AW    = (NUM_BYTES > 1) ? $clog2(NUM_BYTES) : 1;
(* ram_style = "block" *) reg [7:0] rom [0:NUM_BYTES-1];

initial begin
    $readmemh(HEX_FILE, rom);
end

reg [BYTE_AW-1:0] byte_addr;
reg [2:0]         bit_offset;

always @(posedge clk_pdm) begin
    if (!rst_n) begin
        byte_addr  <= {BYTE_AW{1'b0}};
        bit_offset <= 3'd7; // MSB first
        pdm_out    <= 1'b0;
        bit_idx    <= 0;
    end else if (play_en) begin
        // Shift out current bit
        pdm_out <= rom[byte_addr][bit_offset];
        bit_idx <= (byte_addr << 3) + (7 - bit_offset);

        if (bit_offset == 3'd0) begin
            bit_offset <= 3'd7;
            if (byte_addr >= NUM_BYTES - 1)
                byte_addr <= 0; // Loop playback
            else
                byte_addr <= byte_addr + 1'b1;
        end else begin
            bit_offset <= bit_offset - 1'b1;
        end
    end
end

endmodule
